import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh } = ctx.THREE;

  // 1. Scene setup root
  const root = new ThreeGroup();

  // 2. Destructure colors and config tokens
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const primaryText = textContent.find(({ role }) => role === 'headline')?.text ?? 'Pricing 3';

  // 3. Stage backdrop: Engineered vertical gradient (7x6 at z=-2.5)
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ depthWrite: false });

  // Create gradient from surface to ink
  const colorBottom = vec3(new Color(colors.surface));
  const colorTop = vec3(new Color(colors.ink));
  backdropMat.colorNode = mix(colorBottom, colorTop, uv().y);

  const backdrop = new ThreeMesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // 4. Component container
  const container = new ThreeGroup();
  root.add(container);

  // 5. Card plate / background (sized for "Pricing card 3 label" bounds setup)
  const cardGeo = new PlaneGeometry(2.4, 1.4);
  const cardMat = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.95
  });
  const cardMesh = new ThreeMesh(cardGeo, cardMat);
  container.add(cardMesh);

  // Accent edge at the top
  const accentGeo = new PlaneGeometry(2.4, 0.04);
  const accentMat = new MeshBasicNodeMaterial({ color: new Color(colors.accent) });
  const accentMesh = new ThreeMesh(accentGeo, accentMat);
  accentMesh.position.set(0, 0.68, 0.01);
  container.add(accentMesh);

  // Optional: Image loading from config if exists
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      // Instead of overriding completely, we can map the textured element
      const imageGeo = new PlaneGeometry(2.2, 0.8);
      const imageMat = new MeshBasicNodeMaterial({
        map: texture,
        transparent: true,
        opacity: 0.85
      });
      const imageMesh = new ThreeMesh(imageGeo, imageMat);
      imageMesh.position.set(0, 0.1, 0.02);
      container.add(imageMesh);
    }).catch((err) => {
      console.warn('Failed to load pricing image texture:', err);
    });
  }

  // 6. Typography rendering using ctx.fontAtlas
  // Display font sizes: headline 0.18 for card layout, mono status label 0.09
  const labelText = ctx.fontAtlas.createText(primaryText, {
    fontSize: 0.18,
    color: colors.paper,
    align: 'center'
  });
  labelText.position.set(0, -0.4, 0.03);
  container.add(labelText);

  // Static label caption (mono)
  const captionText = ctx.fontAtlas.createText('ATELIER TRADING TIER', {
    fontSize: 0.075,
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 0.1
  });
  captionText.position.set(0, -0.55, 0.03);
  container.add(captionText);

  // 7. Rise-in entrance animation
  container.position.y = -0.3;
  container.scale.setScalar(0.95);

  const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
  tl.to(container.position, { y: 0, duration: 0.8 }, 0);
  tl.to(container.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);

  // 8. Apply dynamic primitives if passed via config
  const customPrimitives = [];
  if (config.cinematicPrimitives) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        const inst = ctx.primitives[primitive.name](container, primitive.params);
        customPrimitives.push(inst);
      }
    }
  }

  // 9. Cleanup hook
  root.userData = {
    cleanup() {
      tl.kill();
      backdropGeo.dispose();
      backdropMat.dispose();
      cardGeo.dispose();
      cardMat.dispose();
      accentGeo.dispose();
      accentMat.dispose();
      customPrimitives.forEach((p) => {
        if (p && typeof p.cleanup === 'function') p.cleanup();
      });
    }
  };

  return root;
}
